import winston from 'winston';
import { config } from '../config/index.js';

// 专门为STDIO模式创建的logger，避免污染JSON输出
export function createStdioLogger() {
  return winston.createLogger({
    level: config.logging.level,
    format: winston.format.combine(
      winston.format.timestamp(),
      winston.format.errors({ stack: true }),
      winston.format.json()
    ),
    defaultMeta: { service: 'get-notes-mcp' },
    transports: [
      // 只在文件和错误级别输出，不输出到控制台
      new winston.transports.File({ 
        filename: 'logs/error.log', 
        level: 'error',
        maxsize: config.logging.maxSize,
        maxFiles: config.logging.maxFiles
      }),
      new winston.transports.File({ 
        filename: 'logs/combined.log',
        maxsize: config.logging.maxSize,
        maxFiles: config.logging.maxFiles
      })
    ]
  });
}

// 创建一个只在非STDIO模式下使用的logger
export function createConditionalLogger() {
  const isStdio = process.env.MCP_TRANSPORT === 'stdio';
  
  if (isStdio) {
    return createStdioLogger();
  }
  
  return winston.createLogger({
    level: config.logging.level,
    format: winston.format.combine(
      winston.format.timestamp(),
      winston.format.errors({ stack: true }),
      winston.format.json()
    ),
    defaultMeta: { service: 'get-notes-mcp' },
    transports: [
      new winston.transports.Console({
        format: winston.format.combine(
          winston.format.colorize(),
          winston.format.simple()
        )
      }),
      new winston.transports.File({ 
        filename: 'logs/error.log', 
        level: 'error',
        maxsize: config.logging.maxSize,
        maxFiles: config.logging.maxFiles
      }),
      new winston.transports.File({ 
        filename: 'logs/combined.log',
        maxsize: config.logging.maxSize,
        maxFiles: config.logging.maxFiles
      })
    ]
  });
}